"""两个 L0 高级查询；统一 Dispatcher 负责 Policy、Evidence、审计与 Replay。"""

from typing import Literal

from pydantic import model_validator

from app.connectors.changes.base import (
    ArgoCDConnector,
    CIConnector,
    ConfigCenterConnector,
    GitConnector,
)
from app.connectors.changes.models import (
    BuildRecord,
    CodeComparison,
    ConfigComparison,
    DeploymentQuery,
    DeploymentRecord,
    VersionQuery,
)
from app.policy.models import RiskLevel
from app.tools.models import ToolModel
from app.tools.registry import ToolRegistry


class CompareVersionsInput(VersionQuery, ToolModel):
    pass


class CompareVersionsOutput(VersionQuery, ToolModel):
    code: CodeComparison
    configuration: ConfigComparison

    @model_validator(mode="after")
    def matching_versions(self) -> "CompareVersionsOutput":
        for result in (self.code, self.configuration):
            if (result.service_name, result.from_version, result.to_version) != (
                self.service_name,
                self.from_version,
                self.to_version,
            ):
                raise ValueError("比较结果与服务或版本不符")
        return self


class RecentDeploymentsInput(DeploymentQuery, ToolModel):
    pass


class RecentDeploymentsOutput(DeploymentQuery, ToolModel):
    history_scope: Literal["source_retained_history"] = "source_retained_history"
    deployments: tuple[DeploymentRecord, ...]
    builds: tuple[BuildRecord, ...]

    @model_validator(mode="after")
    def scoped_records(self) -> "RecentDeploymentsOutput":
        for records in (self.deployments, self.builds):
            if any(
                record.service_name != self.service_name or not self.contains(record.timestamp)
                for record in records
            ):
                raise ValueError("发布或构建结果超出服务与时间范围")
            if len({record.id for record in records}) != len(records):
                raise ValueError("发布或构建结果包含重复记录")
            if list(records) != sorted(
                records, key=lambda record: (record.timestamp, record.id), reverse=True
            ):
                raise ValueError("发布或构建结果必须按时间倒序")
        return self


def register_change_tools(
    registry: ToolRegistry,
    git: GitConnector,
    ci: CIConnector,
    argocd: ArgoCDConnector,
    config_center: ConfigCenterConnector,
) -> None:
    async def compare(query: CompareVersionsInput) -> CompareVersionsOutput:
        request = VersionQuery.model_validate(query.model_dump())
        return CompareVersionsOutput(
            **query.model_dump(),
            code=await git.compare_versions(request),
            configuration=await config_center.compare_versions(request),
        )

    async def recent(query: RecentDeploymentsInput) -> RecentDeploymentsOutput:
        request = DeploymentQuery.model_validate(query.model_dump())
        return RecentDeploymentsOutput(
            **query.model_dump(),
            deployments=await argocd.list_deployments(request),
            builds=await ci.list_builds(request),
        )

    registry.register(
        name="get_recent_deployments",
        description="按服务与 UTC 时间窗倒序读取发布和构建记录",
        input_model=RecentDeploymentsInput,
        output_model=RecentDeploymentsOutput,
        handler=recent,
        risk_level=RiskLevel.L0,
    )
    registry.register(
        name="compare_versions",
        description="读取指定服务两个版本的代码与非敏感配置差异",
        input_model=CompareVersionsInput,
        output_model=CompareVersionsOutput,
        handler=compare,
        risk_level=RiskLevel.L0,
    )

"""唯一调用入口：定级、Policy、执行/回放、证据和审计。无调度与自动重试。"""

from datetime import datetime
from uuid import UUID

from pydantic import ValidationError

from app.db.base import UTCDateTime, utc_now
from app.executor.authority import execution_active, execution_authority
from app.ledger.models import AuditEventType, Evidence
from app.ledger.service import EvidenceNotFound, LedgerService
from app.policy.engine import PolicyEngine
from app.policy.models import PolicyAction, PolicyDecision, PolicyResult, RiskLevel
from app.tasks.models import AITask
from app.tasks.service import TaskNotFound
from app.tools.models import DispatchMode, DispatchResult, DispatchStatus, JsonObject
from app.tools.registry import ToolNotFound, ToolRegistry, _RegisteredTool, json_object


class ToolDispatcher:
    def __init__(self, registry: ToolRegistry, policy: PolicyEngine, ledger: LedgerService) -> None:
        self._registry = registry
        self._policy = policy
        self._ledger = ledger

    async def dispatch(
        self,
        *,
        task_id: UUID,
        tool_name: str,
        parameters: JsonObject,
        actor: str,
        mode: DispatchMode = DispatchMode.LIVE,
        replay_evidence_id: UUID | None = None,
        replay_before: datetime | None = None,
        allowed_tools: frozenset[str] | None = None,
    ) -> DispatchResult:
        session = self._ledger.session
        if not session.in_transaction():
            raise RuntimeError("调用 Dispatcher 前请使用 async with session.begin() 开启事务")
        if not isinstance(mode, DispatchMode):
            raise TypeError("调用模式必须使用 DispatchMode")
        actor = actor.strip()
        if not actor or len(actor) > 200:
            raise ValueError("actor 必须非空且不超过 200 字符")
        # 身份与模式来自宿主服务；Agent 不能传入风险、环境或 approved 布尔值。
        action = PolicyAction(name=tool_name)
        if len(tool_name) > 64:
            raise ValueError("Tool 名称不能超过 64 字符")
        if await session.get(AITask, task_id) is None:
            raise TaskNotFound(f"任务不存在：{task_id}")
        try:
            tool = self._registry._get(tool_name)
        except ToolNotFound:
            return await self._record(
                task_id, actor, mode, self._policy.evaluate(action), error_code="tool_not_found"
            )
        policy = self._policy.evaluate(
            PolicyAction(name=tool_name, risk_level=tool.declaration.risk_level)
        )
        if mode is DispatchMode.LIVE and (
            policy.risk_level is not RiskLevel.L0 or tool_name == "execute_action"
        ):
            # 锁存记录永久阻断写动作，包括旧审批、恢复状态与直接 Dispatcher 调用。
            # Replay 仍读取历史快照，绝不签发凭证。
            if any(
                evidence.source_tool == "safety.abort"
                for evidence in await self._ledger.evidence_for_task(task_id)
            ):
                return await self._record(
                    task_id, actor, mode, policy, error_code="automation_aborted"
                )
        authority = (
            execution_authority(task_id, parameters, id(session))
            if tool_name == "execute_action"
            else None
        )
        if authority is not None:
            current_policy = self._policy.evaluate(
                PolicyAction(
                    name=authority.policy.action_name,
                    risk_level=authority.policy.risk_level,
                    runbook=authority.runbook,
                )
            )
            if current_policy != authority.policy:
                return await self._record(
                    task_id, actor, mode, current_policy, error_code="execution_policy_changed"
                )
            policy = current_policy
        if allowed_tools is not None and tool_name not in allowed_tools:
            return await self._record(
                task_id, actor, mode, policy, error_code="expert_tool_not_allowed"
            )
        if policy.decision is PolicyDecision.DENY or (
            policy.decision is PolicyDecision.NEED_APPROVAL and authority is None
        ):
            code = (
                "approval_required"
                if policy.decision is PolicyDecision.NEED_APPROVAL
                else "policy_denied"
            )
            return await self._record(task_id, actor, mode, policy, error_code=code)
        if (
            mode is DispatchMode.LIVE
            and (policy.risk_level is not RiskLevel.L0 or tool_name == "execute_action")
            and authority is None
        ):
            # 写入仅对 Executor 已验收的精确计划开放，其他 Tool 保持原门禁。
            return await self._record(
                task_id, actor, mode, policy, error_code="write_execution_not_ready"
            )
        try:
            model, normalized = tool.prepare(parameters)
        except (ValidationError, ValueError, TypeError):
            return await self._record(task_id, actor, mode, policy, error_code="invalid_parameters")
        if mode is DispatchMode.REPLAY:
            return await self._replay(
                task_id, actor, policy, tool, normalized, replay_evidence_id, replay_before
            )
        if replay_evidence_id is not None or replay_before is not None:
            return await self._record(task_id, actor, mode, policy, error_code="invalid_replay")
        try:
            result = tool.validate_result(await tool.invoke(model))
        except Exception:
            # 错误内容可能带源系统凭证；仅留下固定错误码，不存异常文本。
            return await self._record(
                task_id, actor, mode, policy, error_code="tool_failed", failed=True
            )
        # savepoint 保证证据与审计成对写入；外层事务仍由调用方提交。
        async with session.begin_nested():
            evidence = await self._ledger.append_evidence(
                task_id=task_id,
                source_tool=tool_name,
                parameters=normalized,
                result_snapshot=result,
                collected_at=utc_now(),
            )
            return await self._record(
                task_id, actor, mode, policy, result=result, evidence=evidence
            )

    async def _replay(
        self,
        task_id: UUID,
        actor: str,
        policy: PolicyResult,
        tool: _RegisteredTool,
        parameters: JsonObject,
        evidence_id: UUID | None,
        before: datetime | None,
    ) -> DispatchResult:
        mode = DispatchMode.REPLAY
        try:
            cutoff = UTCDateTime.normalize(before)
        except (ValueError, TypeError):
            cutoff = None
        if evidence_id is None or cutoff is None:
            return await self._record(task_id, actor, mode, policy, error_code="invalid_replay")
        try:
            evidence = await self._ledger.get_evidence(evidence_id)
        except EvidenceNotFound:
            return await self._record(
                task_id, actor, mode, policy, error_code="replay_evidence_not_found"
            )
        if (
            evidence.task_id != task_id
            or evidence.source_tool != tool.declaration.name
            or evidence.parameters != parameters
            or evidence.collected_at > cutoff
            or (evidence.created_at is not None and evidence.created_at > cutoff)
        ):
            return await self._record(task_id, actor, mode, policy, error_code="replay_mismatch")
        # 只回放有成功调用审计且包含可校验快照的历史结果；绝不联网补查。
        audits = await self._ledger.audits_for_task(task_id)
        if not any(
            audit.event_type is AuditEventType.TOOL_CALL
            and audit.operation == tool.declaration.name
            and audit.evidence_id == evidence_id
            and audit.outcome == DispatchStatus.SUCCEEDED.value
            and audit.occurred_at <= cutoff
            and (audit.created_at is None or audit.created_at <= cutoff)
            and audit.details.get("mode") == DispatchMode.LIVE.value
            for audit in audits
        ):
            return await self._record(
                task_id, actor, mode, policy, error_code="replay_missing_success_audit"
            )
        try:
            result = tool.validate_snapshot(evidence.result_snapshot)
        except (ValidationError, ValueError, TypeError):
            return await self._record(
                task_id, actor, mode, policy, error_code="replay_invalid_snapshot"
            )
        return await self._record(task_id, actor, mode, policy, result=result, evidence=evidence)

    async def _record(
        self,
        task_id: UUID,
        actor: str,
        mode: DispatchMode,
        policy: PolicyResult,
        *,
        result: JsonObject | None = None,
        evidence: Evidence | None = None,
        error_code: str | None = None,
        failed: bool = False,
    ) -> DispatchResult:
        status = (
            DispatchStatus.FAILED
            if failed
            else DispatchStatus.REJECTED
            if error_code is not None
            else DispatchStatus.REPLAYED
            if mode is DispatchMode.REPLAY
            else DispatchStatus.SUCCEEDED
        )
        audit = await self._ledger.append_audit(
            task_id=task_id,
            event_type=AuditEventType.TOOL_CALL,
            actor=actor,
            operation=(
                "execute_action"
                if execution_active(task_id, id(self._ledger.session))
                else policy.action_name
            ),
            outcome=status.value,
            details={
                "mode": mode.value,
                "policy": json_object(policy.model_dump(mode="json")),
                "error_code": error_code,
            },
            evidence_id=None if evidence is None else evidence.id,
        )
        return DispatchResult(
            status=status,
            policy=policy,
            audit_id=audit.id,
            evidence_id=None if evidence is None else evidence.id,
            result=None if result is None else json_object(result),
            error_code=error_code,
        )

"""只声明和注册 Tool；实现函数仅由 Dispatcher 取得并调用。"""

import json
from collections.abc import Awaitable, Callable
from dataclasses import dataclass
from inspect import iscoroutinefunction
from typing import cast

from pydantic import BaseModel, JsonValue

from app.policy.models import PolicyAction, RiskLevel
from app.tools.models import JsonObject, ToolDeclaration, ToolModel


class DuplicateTool(ValueError):
    pass


class ToolNotFound(LookupError):
    pass


def json_object(value: object) -> JsonObject:
    """拒绝非 JSON 数据并深复制，避免参数或结果在留痕前被修改。"""

    def validate(item: object) -> None:
        if isinstance(item, dict):
            for key, child in item.items():
                if not isinstance(key, str):
                    raise ValueError("Tool JSON 对象的键必须为字符串")
                validate(child)
        elif isinstance(item, list):
            for child in item:
                validate(child)
        elif item is not None and not isinstance(item, (str, bool, int, float)):
            raise ValueError("Tool 参数和结果只能使用标准 JSON 数据")

    if not isinstance(value, dict):
        raise ValueError("Tool 参数和结果必须为 JSON 对象")
    validate(value)
    return cast(JsonObject, json.loads(json.dumps(value, allow_nan=False)))


@dataclass(frozen=True, slots=True)
class _RegisteredTool:
    declaration: ToolDeclaration
    input_model: type[ToolModel]
    output_model: type[ToolModel]
    invoke: Callable[[BaseModel], Awaitable[BaseModel]]

    def prepare(self, parameters: JsonObject) -> tuple[BaseModel, JsonObject]:
        model = self.input_model.model_validate_json(
            json.dumps(json_object(parameters)), strict=True
        )
        return model, json_object(model.model_dump(mode="json"))

    def validate_result(self, value: object) -> JsonObject:
        model = self.output_model.model_validate(value, strict=True)
        return json_object(model.model_dump(mode="json"))

    def validate_snapshot(self, value: object) -> JsonObject:
        snapshot = json_object(value)
        self.output_model.model_validate_json(json.dumps(snapshot), strict=True)
        # schema 校验不能给历史结果补新默认字段；必须原样返回当时快照。
        return snapshot


class ToolRegistry:
    def __init__(self) -> None:
        self._tools: dict[str, _RegisteredTool] = {}

    def register[Input: ToolModel, Output: ToolModel](
        self,
        *,
        name: str,
        description: str,
        input_model: type[Input],
        output_model: type[Output],
        handler: Callable[[Input], Awaitable[Output]],
        risk_level: RiskLevel | None = None,
    ) -> ToolDeclaration:
        if name in self._tools:
            raise DuplicateTool(f"Tool 名称已注册：{name}")
        if not issubclass(input_model, ToolModel) or not issubclass(output_model, ToolModel):
            raise TypeError("Tool 入出参模型必须继承 ToolModel")
        for model in (input_model, output_model):
            if (
                model.model_config.get("extra") != "forbid"
                or model.model_config.get("strict") is not True
                or model.model_config.get("revalidate_instances") != "always"
            ):
                raise TypeError("Tool 模型不能放宽严格校验和未声明字段限制")
        # callable 只判断可调用；这里还要确认 callable 对象的实现为 async。
        async_call = getattr(handler, "__call__", None)  # noqa: B004
        if not callable(handler) or not (
            iscoroutinefunction(handler) or iscoroutinefunction(async_call)
        ):
            raise TypeError("Tool 实现必须为异步函数")
        declaration = ToolDeclaration(
            name=name,
            description=description,
            risk_level=PolicyAction.model_validate(
                {"name": name, "risk_level": risk_level}
            ).risk_level,
            input_schema=cast(dict[str, JsonValue], input_model.model_json_schema()),
            output_schema=cast(dict[str, JsonValue], output_model.model_json_schema()),
        )

        async def invoke(model: BaseModel) -> BaseModel:
            if not isinstance(model, input_model):
                raise TypeError("Tool 入参类型不匹配")
            return await handler(model)

        self._tools[name] = _RegisteredTool(declaration, input_model, output_model, invoke)
        return declaration.model_copy(deep=True)

    def _get(self, name: str) -> _RegisteredTool:
        try:
            return self._tools[name]
        except KeyError as error:
            raise ToolNotFound(f"Tool 未注册：{name}") from error

    def declarations(self) -> tuple[ToolDeclaration, ...]:
        return tuple(
            self._tools[name].declaration.model_copy(deep=True) for name in sorted(self._tools)
        )

"""L0 查询只读数据库，Policy、Evidence、审计与 Replay 复用统一 Dispatcher。"""

from datetime import UTC, datetime, timedelta
from typing import Literal

from pydantic import AwareDatetime, Field, field_validator, model_validator

from app.connectors.changes.models import ServiceName
from app.db.base import utc_now
from app.graph.changes.schemas import ChangeView
from app.graph.changes.service import TimelineService
from app.policy.models import RiskLevel
from app.tools.models import ToolModel
from app.tools.registry import ToolRegistry


class RecentChangesInput(ToolModel):
    service_name: ServiceName
    lookback_seconds: int = Field(default=3600, ge=1, le=2592000)
    end: AwareDatetime | None = None

    @field_validator("end")
    @classmethod
    def utc(cls, value: datetime | None) -> datetime | None:
        return value.astimezone(UTC) if value is not None else None


class RecentChangesOutput(ToolModel):
    service_name: ServiceName
    start: AwareDatetime
    end: AwareDatetime
    history_scope: Literal["collected_source_history"] = "collected_source_history"
    events: tuple[ChangeView, ...]

    @model_validator(mode="after")
    def scope(self) -> "RecentChangesOutput":
        if self.start >= self.end or any(
            e.service_name != self.service_name or not self.start <= e.occurred_at < self.end
            for e in self.events
        ):
            raise ValueError("变更结果超出服务或时间范围")
        if len({e.identity for e in self.events}) != len(self.events):
            raise ValueError("变更结果重复")
        if tuple(e.occurred_at for e in self.events) != tuple(
            sorted(e.occurred_at for e in self.events)
        ):
            raise ValueError("变更结果必须按时间升序")
        return self


def register_timeline_tools(registry: ToolRegistry, timeline: TimelineService) -> None:
    async def recent(query: RecentChangesInput) -> RecentChangesOutput:
        end = query.end if query.end is not None else utc_now()
        start = end - timedelta(seconds=query.lookback_seconds)
        return RecentChangesOutput(
            service_name=query.service_name,
            start=start,
            end=end,
            events=await timeline.recent(query.service_name, start, end),
        )

    registry.register(
        name="get_recent_changes",
        description="按服务与 UTC 时间窗升序读取已采集变更引用",
        input_model=RecentChangesInput,
        output_model=RecentChangesOutput,
        handler=recent,
        risk_level=RiskLevel.L0,
    )

"""事件接入与 Watch 参数；凭证只通过环境变量注入。"""

from pydantic import BaseModel, ConfigDict, Field, SecretStr, field_validator


class TriggerConfig(BaseModel):
    model_config = ConfigDict(frozen=True, extra="forbid", hide_input_in_errors=True)

    webhook_secrets: dict[str, SecretStr] = Field(default_factory=dict, repr=False)
    signature_max_age_seconds: int = Field(default=300, ge=1, le=3600)
    max_body_bytes: int = Field(default=262144, ge=1024, le=1048576)
    response_timeout_seconds: int = Field(default=15, ge=1, le=60)
    watcher_enabled: bool = False
    watcher_namespaces: tuple[str, ...] = ("payment",)
    watch_timeout_seconds: int = Field(default=20, ge=1, le=60)

    @field_validator("webhook_secrets")
    @classmethod
    def check_secrets(cls, value: dict[str, SecretStr]) -> dict[str, SecretStr]:
        allowed = {
            "prometheus",
            "ops_platform",
            "git",
            "ci",
            "argocd",
            "config_center",
            "cloud",
            "manual",
        }
        if any(
            name not in allowed or len(secret.get_secret_value()) < 32
            for name, secret in value.items()
        ):
            raise ValueError("Webhook 来源必须受支持，且每个签名密钥至少 32 字符")
        return value

    @field_validator("watcher_namespaces")
    @classmethod
    def check_namespaces(cls, value: tuple[str, ...]) -> tuple[str, ...]:
        from pydantic import TypeAdapter

        from app.connectors.kubernetes.models import Namespace

        if not value or len(value) != len(set(value)):
            raise ValueError("Watcher 命名空间必须非空且不能重复")
        for namespace in value:
            TypeAdapter(Namespace).validate_python(namespace)
        return value

"""采集与原子入库在 Activity；失败由 Temporal 有限重试。"""

from contextlib import AsyncExitStack
from datetime import datetime

from temporalio import activity
from temporalio.exceptions import ApplicationError

from app.config import Settings
from app.connectors.kubernetes.factory import create_kubernetes_connector
from app.connectors.observability.factory import create_prometheus_connector
from app.db.base import UTCDateTime
from app.db.session import Database
from app.triggers.detection.models import (
    DetectionBatch,
    DetectionRequest,
    DetectionResult,
    Observation,
)
from app.triggers.detection.service import DetectionService
from app.triggers.detection.sources import DetectionSources


class DetectionActivities:
    def __init__(self, database: Database, settings: Settings) -> None:
        self.database, self.settings = database, settings

    @activity.defn(name="detection.collect")
    async def collect(self, value: DetectionRequest) -> DetectionBatch:
        try:
            at = UTCDateTime.normalize(datetime.fromisoformat(value.observed_at))
            if at is None:
                raise ValueError
        except (ValueError, TypeError):
            raise ApplicationError("检测采集时间无效", non_retryable=True) from None
        try:
            async with AsyncExitStack() as stack:
                kubernetes = await stack.enter_async_context(
                    create_kubernetes_connector(self.settings)
                )
                prometheus = await stack.enter_async_context(
                    create_prometheus_connector(self.settings)
                )
                values = await DetectionSources(kubernetes, prometheus).collect(
                    self.settings.detection_config, at
                )
            return DetectionBatch(at.isoformat(), [value.model_dump_json() for value in values])
        except Exception:
            raise ApplicationError("状态或趋势采集失败，请检查检测配置及只读来源") from None

    @activity.defn(name="detection.persist")
    async def persist(self, value: DetectionBatch) -> DetectionResult:
        try:
            at = UTCDateTime.normalize(datetime.fromisoformat(value.observed_at))
            if at is None or len(value.observations) > 10000:
                raise ValueError
            values = [Observation.model_validate_json(item) for item in value.observations]
        except (ValueError, TypeError):
            raise ApplicationError("检测入库参数无效", non_retryable=True) from None
        try:
            async with self.database.session() as session, session.begin():
                return await DetectionService(session).persist(values, at.isoformat())
        except Exception:
            raise ApplicationError("检测事件、证据或游标写入失败") from None

    async def evaluate(self, value: DetectionRequest) -> DetectionResult:
        return await self.persist(await self.collect(value))

"""只保存检测游标及当前异常事件引用，原始序列保留在源系统。"""

from dataclasses import dataclass
from datetime import datetime
from uuid import UUID

from pydantic import AwareDatetime, BaseModel, ConfigDict, Field, JsonValue, field_validator
from sqlalchemy import CheckConstraint, ForeignKey, String, UniqueConstraint
from sqlalchemy.orm import Mapped, mapped_column

from app.db.base import Base, UTCDateTime
